import type { Landmark, PlaceKind } from '../game/types';
import catalog from '../../assets/places/catalog.json';

// Generated by scripts/ingest-places.py. Source geometry/record IDs are official;
// a road snap is a game pickup proxy, not a verified legal entrance.
type CompactPlace = [
  id: string, name: string, nameEn: string, district: string,
  districtCode: string, kind: PlaceKind, lat: number, lon: number,
  nodeId: string, snapDistanceM: number, waitingProfile: 'ordinary' | 'saikung',
  sourceId: string, sourceRecordId: string, geoRefNo: string,
  coordinateBasis: 'footprint-centroid' | 'official-point',
];

export const POI_CATALOG_VERSION = 'landsd-hk-2026-11-18-v2';
export const POI_ATTRIBUTION = catalog.attribution;
export const POI_TERMS_URL = catalog.termsUrl;

export const LANDMARKS: Landmark[] = (catalog.rows as unknown as CompactPlace[]).map((row) => ({
  id: row[0], name: row[1], nameEn: row[2], district: row[3],
  kind: row[5], lat: row[6], lon: row[7], nodeId: row[8],
  snapDistanceM: row[9], waitingProfile: row[10], sourceRecordId: row[12],
}));

export const LANDMARK_BY_ID = new Map(LANDMARKS.map((place) => [place.id, place]));
